-- Name: inactivar_beneficiarios(); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.inactivar_beneficiarios() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.activo = false AND OLD.activo = true THEN
    UPDATE public.beneficiarios
      SET activo = false
      WHERE empleado_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


