-- Name: transicion_estado(bigint, public.atencion_estado_t, integer, text); Type: FUNCTION; Schema: public; Owner: postgres
--

CREATE FUNCTION public.transicion_estado(p_cola_id bigint, p_estado public.atencion_estado_t, p_por integer DEFAULT NULL::integer, p_observacion text DEFAULT NULL::text) RETURNS public.cola_atencion
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_fila public.cola_atencion;
  v_estado_anterior public.atencion_estado_t;
BEGIN
  SELECT * INTO v_fila FROM public.cola_atencion WHERE id = p_cola_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Atención % no encontrada', p_cola_id;
  END IF;
  v_estado_anterior := v_fila.atencion_estado;

  -- Actualizar la fila + timestamp correspondiente
  UPDATE public.cola_atencion SET
    atencion_estado = p_estado,
    fec_triaje   = CASE WHEN p_estado = 'TRIAJE'              THEN now() ELSE fec_triaje END,
    fec_encolada = CASE WHEN p_estado = 'EN_ESPERA_CONSULTA'  THEN now() ELSE fec_encolada END,
    iniciado_en  = CASE WHEN p_estado = 'EN_CONSULTA'         THEN now() ELSE iniciado_en END,
    fin_en       = CASE WHEN p_estado IN ('FINALIZADO','CANCELADO','NO_ASISTIO') THEN now() ELSE fin_en END,
    cancelado_en = CASE WHEN p_estado IN ('CANCELADO','NO_ASISTIO') THEN now() ELSE cancelado_en END
  WHERE id = p_cola_id
  RETURNING * INTO v_fila;

  -- Trazar el cambio

  RETURN v_fila;
END;
$$;


