--
-- TOC entry 248 (class 1259 OID 17169)
-- Name: v_cola_atencion; Type: VIEW; Schema: public; Owner: postgres
--

CREATE VIEW public.v_cola_atencion AS
 SELECT c.id,
    c.token,
    c.paciente_id,
    c.paciente_cedula,
    c.paciente_nombre,
    c.clinica_id,
    c.atencion_estado,
    c.ruta_atencion,
    c.prioridad,
    c.triaje_realizado,
    c.sintomas_principales,
    c.presion_sistolica,
    c.presion_diastolica,
    c.temperatura,
    c.peso_kg,
    c.frecuencia_cardiaca,
    c.frecuencia_respiratoria,
    c.saturacion_oxigeno,
    c.glucometria,
    c.nivel_conciencia,
    c.motivo_consulta,
    c.especialidad,
    c.medico_id,
    COALESCE(((p.nombre || ' '::text) || p.apellido), ''::text) AS medico_nombre,
    c.cita_id,
    c.creado_en,
    c.fec_triaje,
    c.fec_encolada,
    c.iniciado_en,
    c.fin_en,
    c.cancelado_en,
    c.consulta_id,
    c.nivel_prioridad,
    c.cuota_prioritaria,
    c.derivado_a_especialista,
    c.especialista_id,
    c.clasificacion_origen,
    c.observaciones,
    COALESCE(cc.codigo_confirmacion, ''::text) AS cita_codigo
   FROM ((public.cola_atencion c
     LEFT JOIN public.personal p ON ((p.id = c.medico_id)))
     LEFT JOIN public.citas cc ON ((cc.id = c.cita_id)));


ALTER VIEW public.v_cola_atencion OWNER TO postgres;

